function cleanString(value) {
  if (value === null || value === undefined) {
    return '';
  }

  return String(value).trim();
}

function normalizeEmail(value) {
  return cleanString(value).toLowerCase();
}

function normalizeYesNo(value) {
  const text = cleanString(value).toLowerCase();

  if (['yes', 'y', 'true'].includes(text)) {
    return 'YES';
  }

  if (['no', 'n', 'false'].includes(text)) {
    return 'NO';
  }

  return '';
}

function normalizePhone(value, location = '') {
  let phone = cleanString(value);

  if (!phone) return '';

  phone = phone.replace(/[^\d+]/g, '');

  const hasPlus = phone.startsWith('+');

  let digits = phone.replace(/\+/g, '');

  if (digits.startsWith('0')) {
    const locationText = cleanString(location).toLowerCase();

    const isNigeria =
      locationText.includes('nigeria') ||
      locationText === 'ng';

    if (isNigeria) {
      digits = '234' + digits.substring(1);
    } else {
      return phone;
    }
  }

  if (digits.startsWith('234')) {
    return '+' + digits;
  }

  if (hasPlus) {
    return '+' + digits;
  }

  return phone;
}

function isValidEmail(value) {
  const email = normalizeEmail(value);

  return /^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(email);
}

function isValidPhone(value) {
  const phone = cleanString(value);

  if (!phone) return false;

  const digits = phone.replace(/\D/g, '');

  return digits.length >= 10 && digits.length <= 15;
}

function normalizeAge(value) {
  if (value === null || value === undefined || value === '') {
    return '';
  }

  const raw = String(value).trim().toLowerCase();

  // Extract a number from inputs such as:
  // "24", "24 years", "24 years old", "I am 24", "8 yrs"
  const numericMatch = raw.match(/\b\d{1,3}\b/);

  if (numericMatch) {
    return Number(numericMatch[0]);
  }

  const numberWords = {
    zero: 0,
    one: 1,
    two: 2,
    three: 3,
    four: 4,
    five: 5,
    six: 6,
    seven: 7,
    eight: 8,
    nine: 9,
    ten: 10,
    eleven: 11,
    twelve: 12,
    thirteen: 13,
    fourteen: 14,
    fifteen: 15,
    sixteen: 16,
    seventeen: 17,
    eighteen: 18,
    nineteen: 19,
    twenty: 20,
    thirty: 30,
    forty: 40,
    fifty: 50,
    sixty: 60,
    seventy: 70,
    eighty: 80,
    ninety: 90
  };

  const words = raw.replace(/-/g, ' ').split(/\s+/);

  // Example: "eight"
  if (
    words.length === 1 &&
    numberWords[words[0]] !== undefined
  ) {
    return numberWords[words[0]];
  }

  // Examples: "twenty four", "twenty-four"
  if (words.length === 2) {
    const tens = numberWords[words[0]];
    const ones = numberWords[words[1]];

    if (
      tens !== undefined &&
      tens >= 20 &&
      tens % 10 === 0 &&
      ones !== undefined &&
      ones >= 1 &&
      ones <= 9
    ) {
      return tens + ones;
    }
  }

  // Examples:
  // "I am twenty four years old"
  // "twenty four years"
  const relevantWords = words.filter(
    word => numberWords[word] !== undefined
  );

  if (relevantWords.length >= 1) {
    const tensWord = relevantWords.find(
      word =>
        numberWords[word] >= 20 &&
        numberWords[word] % 10 === 0
    );

    const onesWord = relevantWords.find(
      word =>
        numberWords[word] >= 1 &&
        numberWords[word] <= 9
    );

    if (tensWord && onesWord) {
      return numberWords[tensWord] + numberWords[onesWord];
    }

    if (relevantWords.length === 1) {
      return numberWords[relevantWords[0]];
    }
  }

  return '';
}

function isValidAge(value) {
  const age = normalizeAge(value);

  return Number.isInteger(age) && age >= 13 && age <= 100;
}

function hasValue(value) {
  return cleanString(value) !== '';
}

function isLikelyTestResponse(data) {
  const testTerms = [
    'test',
    'testing',
    'dummy',
    'sample',
    'fake'
  ];

  const fieldsToCheck = [
    data['Full Name'],
    data['Email'],
    data['Situation'],
    data['Self Description']
  ];

  const combined = fieldsToCheck
    .map(value => cleanString(value).toLowerCase())
    .join(' ');

  return testTerms.some(term => combined.includes(term));
}

function normalizeTimestamp(value) {
  if (!hasValue(value)) {
    return '';
  }

  const numericValue = Number(value);

  // Google Sheets serial date
  if (!Number.isNaN(numericValue)) {
    const baseDate = new Date(Date.UTC(1899, 11, 30));

    const date = new Date(
      baseDate.getTime() +
      numericValue * 24 * 60 * 60 * 1000
    );

    return date.toISOString();
  }

  const parsedDate = new Date(value);

  if (!Number.isNaN(parsedDate.getTime())) {
    return parsedDate.toISOString();
  }

  return cleanString(value);
}

function getLocationCountry(location) {
  const text = cleanString(location);

  if (!text) return '';

  const parts = text.split(',');

  if (parts.length >= 2) {
    return cleanString(
      parts[parts.length - 1]
    ).toUpperCase();
  }

  const lower = text.toLowerCase();

  if (lower === 'nigeria') {
    return 'NIGERIA';
  }

  if (lower === 'ng') {
    return 'NG';
  }

  return '';
}

function getLeadRegion(location) {
  const country = getLocationCountry(location);

  if (
    country === 'NIGERIA' ||
    country === 'NG'
  ) {
    return 'NIGERIA';
  }

  if (country) {
    return 'INTERNATIONAL';
  }

  return 'UNKNOWN';
}

function isInternationalLead(location) {
  const region = getLeadRegion(location);

  if (region === 'INTERNATIONAL') {
    return 'YES';
  }

  if (region === 'NIGERIA') {
    return 'NO';
  }

  return '';
}


// --------------------------------------------------
// MAIN PROCESSING
// --------------------------------------------------

const data = $json;

const fullName = cleanString(
  data['Full Name']
);

const email = normalizeEmail(
  data['Email']
);

const location = cleanString(
  data['Location']
);

const whatsapp = normalizePhone(
  data['Whatsapp'],
  location
);

const age = normalizeAge(
  data['Age']
);

const socialStatus = cleanString(
  data['Social status']
);

const paymentClaimed = normalizeYesNo(
  data['Payment claimed']
);

const followUpRequested = normalizeYesNo(
  data['Followup requested']
);

const situationResponse = cleanString(
  data['Situation']
);

const selfDescription = cleanString(
  data['Self Description']
);

const proofOfPayment = cleanString(
  data['Proof of Payment']
);

const dateSubmitted = normalizeTimestamp(
  data['Submitted at']
);

// Meta attribution
const metaClickId = cleanString(
  data['Meta Click ID (please ignore)']
);


// --------------------------------------------------
// VALIDATION
// --------------------------------------------------

const emailValid = isValidEmail(email);

const phoneValid = isValidPhone(whatsapp);

const ageValid = isValidAge(age);

const nameValid = hasValue(fullName);

const locationValid = hasValue(location);

const situationValid = hasValue(
  situationResponse
);

const selfDescriptionValid = hasValue(
  selfDescription
);


// --------------------------------------------------
// ANOMALIES
// --------------------------------------------------

const anomalies = [];

if (!nameValid) {
  anomalies.push('MISSING_NAME');
}

if (!emailValid) {
  anomalies.push('INVALID_EMAIL');
}

if (!phoneValid) {
  anomalies.push('INVALID_PHONE');
}

if (!ageValid) {
  anomalies.push('INVALID_AGE');
}

if (!locationValid) {
  anomalies.push('MISSING_LOCATION');
}

if (!situationValid) {
  anomalies.push('MISSING_SITUATION_RESPONSE');
}

if (!selfDescriptionValid) {
  anomalies.push('MISSING_SELF_DESCRIPTION');
}

if (!paymentClaimed) {
  anomalies.push('MISSING_PAYMENT_CLAIM');
}

if (!followUpRequested) {
  anomalies.push('MISSING_FOLLOWUP_REQUEST');
}


// --------------------------------------------------
// TEST SUBMISSION DETECTION
// --------------------------------------------------

const possibleTestSubmission =
  isLikelyTestResponse(data);

if (possibleTestSubmission) {
  anomalies.push(
    'POSSIBLE_TEST_SUBMISSION'
  );
}


// --------------------------------------------------
// FORM VALIDATION STATUS
// --------------------------------------------------

let formValidationStatus = 'VALID';

if (
  anomalies.includes('INVALID_EMAIL') ||
  anomalies.includes('INVALID_PHONE') ||
  anomalies.includes('INVALID_AGE') ||
  anomalies.includes('MISSING_NAME') ||
  anomalies.includes('MISSING_LOCATION')
) {
  formValidationStatus = 'INVALID';
} else if (anomalies.length > 0) {
  formValidationStatus = 'VALID_WITH_WARNINGS';
}


// --------------------------------------------------
// LEAD ID
// --------------------------------------------------

const dateForId = new Date();

const datePart =
  dateForId.getFullYear().toString() +
  String(
    dateForId.getMonth() + 1
  ).padStart(2, '0') +
  String(
    dateForId.getDate()
  ).padStart(2, '0');

const randomPart = Math.random()
  .toString(36)
  .substring(2, 8)
  .toUpperCase();

const leadId =
  `SRM-${datePart}-${randomPart}`;


// --------------------------------------------------
// LEAD STATUS
// --------------------------------------------------

let leadStatus = 'WARM';

if (paymentClaimed === 'YES') {
  leadStatus = 'PAYMENT CLAIMED';
}


// --------------------------------------------------
// FOLLOW-UP STATUS
// --------------------------------------------------

let followUpStatus = 'PASSIVE';

if (followUpRequested === 'YES') {
  followUpStatus = 'ACTIVE';
}


// --------------------------------------------------
// RETURN CLEAN DATA
// --------------------------------------------------

return {
  json: {
    'Date Submitted': dateSubmitted,
    'Lead ID': leadId,
    'Full Name': fullName,
    'Email Address': email,
    'WhatsApp / Phone': whatsapp,
    'Location': location,
    'Age': age,
    'Social Status': socialStatus,
    'Lead Region': getLeadRegion(location),
    'International Lead?': isInternationalLead(location),
    'Payment Claimed?': paymentClaimed,
    'Proof of Payment': proofOfPayment,
    'Payment Verified?': 'PENDING',
    'Staff Verification Notes': '',
    'AI Analysis Status': 'PENDING',
    'Situation Response': situationResponse,
    'Self-Description': selfDescription,
    'Form Validation Status': formValidationStatus,
    'Form Anomalies': anomalies.join(', '),
    'Possible Test Submission?':
      possibleTestSubmission ? 'YES' : 'NO',
    'Lead Status': leadStatus,
    'Welcome Email Sent?': 'NO',
    'Follow-up Requested?': followUpRequested,
    'Follow-up Status': followUpStatus,
    'Last Updated': new Date().toISOString(),

    // Keep Meta Click ID LAST
    'Meta Click ID': metaClickId
  }
};
